#include <string.h>

size_t RegisterJPEGImage() {
    MagickInfo *magick_info;
    static const char *jpeg_versions[] = {"JPE", "JPEG", "JPG", "JPS", "PJPEG", (char *) NULL};
    const char *version = "6.9.0";
    const char *description = "JPEG image format";

    magick_info = SetMagickInfo("JPEG");
    magick_info->decoder = JPEGDecoder;
    magick_info->encoder = JPEGEncoder;
    magick_info->thread_support = (JPEGVersion() >= 6.9) ? MagickTrue : MagickFalse;
    magick_info->mime_type = "image/jpeg";
    magick_info->description = description;
    magick_info->version = version;

    RegisterMagickInfo(magick_info);

    for (int i = 0; jpeg_versions[i] != NULL; i++) {
        MagickInfo *alt_info = SetMagickInfo(jpeg_versions[i]);
        alt_info->decoder = JPEGDecoder;
        alt_info->encoder = JPEGEncoder;
        alt_info->thread_support = magick_info->thread_support;
        alt_info->mime_type = "image/jpeg";
        alt_info->description = description;
        alt_info->version = version;

        RegisterMagickInfo(alt_info);
    }

    return sizeof(*magick_info);
}

#include <string.h>

size_t RegisterJPEGImage() {
  const char *version = "6.9.10";
  const char *description = "JPEG (Joint Photographic Experts Group) Image";

  size_t entry_size = 0;

  entry_size += SetMagickInfo("JPE", description, version, "image/jpeg", MagickTrue, MagickTrue, DecodeJPEGHandler, EncodeJPEGHandler);
  entry_size += SetMagickInfo("JPEG", description, version, "image/jpeg", MagickTrue, MagickTrue, DecodeJPEGHandler, EncodeJPEGHandler);
  entry_size += SetMagickInfo("JPG", description, version, "image/jpeg", MagickTrue, MagickTrue, DecodeJPEGHandler, EncodeJPEGHandler);
  entry_size += SetMagickInfo("JPS", description, version, "image/jpeg", MagickTrue, MagickTrue, DecodeJPEGHandler, EncodeJPEGHandler);
  entry_size += SetMagickInfo("PJPEG", description, version, "image/jpeg", MagickTrue, MagickTrue, DecodeJPEGHandler, EncodeJPEGHandler);

  if (strcmp(version, "7.0.0") >= 0) {
    entry_size += SetMagickInfo("JPEG2", description, version, "image/jpeg", MagickTrue, MagickTrue, DecodeJPEGHandler, EncodeJPEGHandler);
  }

  RegisterMagickInfo();

  return entry_size;
}

